&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;span data-contrast=&quot;none&quot;&gt;Job Summary:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;This is an exciting role at an innovative, high-growth defense technology company&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot; data-ccp-charstyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;ac0262f4-8a9e-5820-b908-2d943c5f7113|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Calibri&amp;quot;,469777842,&amp;quot;&amp;quot;,469777843,&amp;quot;Calibri&amp;quot;,469777844,&amp;quot;Calibri&amp;quot;,201341986,&amp;quot;1&amp;quot;,469769226,&amp;quot;Calibri&amp;quot;,268442635,&amp;quot;22&amp;quot;,469775450,&amp;quot;normaltextrun&amp;quot;,201340122,&amp;quot;1&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;normaltextrun&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Default Paragraph Font&amp;quot;]}&quot;&gt;The &lt;strong&gt;Senior RF Engineer&lt;/strong&gt; will &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;lead the&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;design&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;&amp;nbsp;o&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;f solid-state power amplifier modules from concept to production&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;. The ideal candidate for the position is someone who has experience with high power amplifier design and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;will have full ownership of&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;&amp;nbsp;product development through all stages of conception, prototype, and productization. In this role, you will work closely with a talented engineering team in a fast-paced environment to apply emerging technologies in innovative ways to rapidly produce new products. This position will report to the Manager of RF Engineering.&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;  &lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;Responsibilities:&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:40,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Design of high-power microwave amplifiers&amp;nbsp;and RF&amp;nbsp;front-end modules&amp;nbsp;for CW or pulsed operation &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Modeling, simulation, analysis, design, test, and optimization of high power active and passive power amplifier circuits &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Generate schematics and work closely with mechanical, thermal, and PCB layout teams to ensure circuit designs meet requirements while striving for first pass design success &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Board bring up, test, and&amp;nbsp;bench level tuning &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Develop&amp;nbsp;design&amp;nbsp;verification test plans and&amp;nbsp;assist&amp;nbsp;with testing &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Evaluate, characterize, and select off-the-shelf power amplifier components like discrete transistors, MMICs, couplers, splitters/combiners, etc. &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
