&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Hold design reviews and presentations with peers and act as a&amp;nbsp;reviewer&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
