&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience with schematic capture and guiding PCB layout &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
